from __future__ import annotations


TEMPLATE_PATH = 'backend/app/api/routes/auth.py'
TEMPLATE_CONTENT = 'from fastapi import APIRouter, Depends, HTTPException, Request\nfrom sqlalchemy.ext.asyncio import AsyncSession\n\nfrom app.api.dependencies import get_current_user_id\nfrom app.core.database import get_db\nfrom app.core.rate_limit import AUTH_RATE_LIMIT, limiter\nfrom app.core.security import create_access_token\nfrom app.schemas.auth import UserLoginRequest, UserRegisterRequest, UserResponse\nfrom app.services.audit_service import create_audit_log\nfrom app.services.auth_service import authenticate_user, create_user\n\n\nrouter = APIRouter()\n\n\n@router.post("/register", response_model=UserResponse)\n@limiter.limit(AUTH_RATE_LIMIT)\nasync def register(\n    request: Request,\n    payload: UserRegisterRequest,\n    db: AsyncSession = Depends(get_db),\n):\n    try:\n        user = await create_user(db=db, payload=payload)\n    except ValueError as error:\n        await create_audit_log(\n            db=db,\n            event_type="user_register_failed",\n            status="failed",\n            route="/api/auth/register",\n            detail=str(error),\n        )\n        raise HTTPException(status_code=400, detail=str(error))\n\n    await create_audit_log(\n        db=db,\n        event_type="user_registered",\n        status="success",\n        actor_user_id=user.id,\n        route="/api/auth/register",\n    )\n\n    access_token = create_access_token(subject=str(user.id))\n\n    return {\n        "access_token": access_token,\n        "token_type": "bearer",\n    }\n\n\n@router.post("/login", response_model=UserResponse)\n@limiter.limit(AUTH_RATE_LIMIT)\nasync def login(\n    request: Request,\n    payload: UserLoginRequest,\n    db: AsyncSession = Depends(get_db),\n):\n    user = await authenticate_user(\n        db=db,\n        username=payload.username,\n        password=payload.password,\n    )\n\n    if not user:\n        await create_audit_log(\n            db=db,\n            event_type="login_failed",\n            status="failed",\n            route="/api/auth/login",\n            detail="Invalid credentials",\n        )\n        raise HTTPException(status_code=401, detail="Invalid credentials")\n\n    await create_audit_log(\n        db=db,\n        event_type="login_success",\n        status="success",\n        actor_user_id=user.id,\n        route="/api/auth/login",\n    )\n\n    access_token = create_access_token(subject=str(user.id))\n\n    return {\n        "access_token": access_token,\n        "token_type": "bearer",\n    }\n\n\n@router.get("/me")\nasync def me(\n    current_user_id: str = Depends(get_current_user_id),\n):\n    return {\n        "user_id": current_user_id,\n    }\n'
